from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
app=ROOT/'src/ui/app.mjs'
text=app.read_text(encoding='utf-8')

def replace_between(src,start,end,new):
    a=src.index(start)
    b=src.index(end,a)
    return src[:a]+new+src[b:]

# Ordinary node connection action participates in the same visual component as Trigger Hub.
text=text.replace('class="brain-stack-action ${source?\'active\':\'\'}" data-brain-connect', 'class="brain-stack-action brain-connect-source-button ${source?\'active\':\'\'}" data-brain-connect')

old_begin="function beginBrainConnection(id){if(replayMode)return;brainConnectFromId=brainConnectFromId===id?null:id;activeBrainNodeId=id;renderBrainCanvas();renderBrainStatus()}"
new_begin="""function beginBrainConnection(id){if(replayMode)return;const same=brainConnectFromId===id,node=fromBrainNode(id);brainConnectFromId=same?null:id;activeBrainNodeId=same?null:id;if(node&&familyOf(node)==='TRIGGER'){activeBrainTriggerId=same?null:id;brainTriggerHubOpen=true}renderBrainCanvas();renderBrainStatus()}"""
assert old_begin in text, 'beginBrainConnection signature changed'
text=text.replace(old_begin,new_begin)

old_delete="function deleteBrainNode(id){if(replayMode)return;removeBrainNode(currentBrainGraph,id);activeBrainNodeId=null;brainConnectFromId=null;activeBrainPresetId='custom';rebuildBrainSequence();renderBrain()}"
new_delete="""function deleteBrainNode(id){if(replayMode)return;const node=fromBrainNode(id);if(!node||familyOf(node)==='TRIGGER')return;removeBrainNode(currentBrainGraph,id);activeBrainNodeId=null;brainConnectFromId=null;activeBrainPresetId='custom';rebuildBrainSequence();renderBrain()}"""
assert old_delete in text, 'deleteBrainNode signature changed'
text=text.replace(old_delete,new_delete)

trigger_block="""function triggerHubHtml(){const triggers=brainTriggerNodes(),active=activeBrainTriggerId&&triggers.some(n=>n.id===activeBrainTriggerId)?activeBrainTriggerId:null;const chips=triggers.map(n=>`<button type=\"button\" class=\"brain-trigger-chip ${n.id===active?'active':''}\" data-trigger-select=\"${n.id}\">${title(n.type)}</button>`).join('');const rows=triggers.map(n=>{const source=n.id===brainConnectFromId,hasRoutes=outgoing(currentBrainGraph,n.id).length>0;return `<div class=\"brain-trigger-row ${n.id===active?'active':''} ${source?'connection-source':''}\" data-trigger-row=\"${n.id}\"><button type=\"button\" class=\"brain-trigger-row__main\" data-trigger-select=\"${n.id}\"><strong>${title(n.type)}</strong><span>${nodeSubtitle(n)}</span><em>→ ${triggerDestination(n)}</em></button>${replayMode?'':`<div class=\"brain-trigger-row__actions\"><button type=\"button\" class=\"brain-connect-source-button ${source?'active':''}\" data-trigger-connect=\"${n.id}\" aria-label=\"Связать ${title(n.type)}\"><img src=\"./assets/ui/brain-connect.svg\" alt=\"\"><span>СВЯЗАТЬ</span></button><button type=\"button\" class=\"brain-trigger-disconnect\" data-trigger-disconnect=\"${n.id}\" ${hasRoutes?'':'disabled'}>ОТКЛЮЧИТЬ</button></div>`}</div>`}).join('');return `<section class=\"brain-trigger-hub ${brainTriggerHubOpen?'open':''}\" data-trigger-hub><button type=\"button\" class=\"brain-trigger-hub__head\" data-trigger-hub-toggle aria-expanded=\"${brainTriggerHubOpen}\"><span><small>ВХОДЫ</small><strong>${triggers.length?'НА ЧТО Я РЕАГИРУЮ':'НА ЧТО ТЫ РЕАГИРУЕШЬ?'}</strong></span><b>${triggers.length}</b><i>${brainTriggerHubOpen?'−':'+'}</i></button>${triggers.length?`<div class=\"brain-trigger-chips\">${chips}</div>`:'<p class=\"brain-trigger-empty\">СИСТЕМНЫЕ ВХОДЫ НЕ НАЙДЕНЫ.</p>'}<div class=\"brain-trigger-hub__body\">${rows}</div></section>`}
function disconnectTriggerRoutes(id){if(replayMode)return;const node=fromBrainNode(id);if(!node||familyOf(node)!=='TRIGGER')return;currentBrainGraph.edges=currentBrainGraph.edges.filter(edge=>edge.from!==id);if(brainConnectFromId===id)brainConnectFromId=null;activeBrainTriggerId=id;activeBrainNodeId=null;activeBrainPresetId='custom';renderBrainCanvas();renderBrainStatus()}
function bindTriggerHub(){const host=$('#brain-graph');host?.querySelector('[data-trigger-hub-toggle]')?.addEventListener('click',()=>{brainTriggerHubOpen=!brainTriggerHubOpen;renderBrainCanvas()});host?.querySelectorAll('[data-trigger-select]').forEach(button=>button.addEventListener('click',()=>{activeBrainTriggerId=activeBrainTriggerId===button.dataset.triggerSelect?null:button.dataset.triggerSelect;brainTriggerHubOpen=true;brainConnectFromId=null;activeBrainNodeId=null;renderBrainCanvas();renderBrainStatus()}));host?.querySelectorAll('[data-trigger-connect]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();beginBrainConnection(button.dataset.triggerConnect)}));host?.querySelectorAll('[data-trigger-disconnect]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();disconnectTriggerRoutes(button.dataset.triggerDisconnect)}))}
"""
text=replace_between(text,'function triggerHubHtml()','function projectedBrainNodeHtml',trigger_block)

library_block="""function libraryNodeValue(spec){const fake={type:spec.type,p:{...(spec.defaults||{})}};return nodeValue(fake)}
function libraryNodeHtml(spec,family){const system=family==='TRIGGER',value=libraryNodeValue(spec);return `<button type=\"button\" class=\"brain-library-node ${system?'system-trigger':''}\" ${system?`data-open-trigger-type=\"${spec.type}\"`:`data-add-brain-node=\"${spec.type}\"`} data-node-family=\"${family}\"><span class=\"brain-library-node__family\">${family.toLowerCase()}</span><strong class=\"brain-library-node__title\">${spec.title}</strong><span class=\"brain-library-node__description\">${nodeSubtitle({type:spec.type})}</span>${value?`<b class=\"brain-library-node__value\">${value}</b>`:''}${system?'<em class=\"brain-library-node__system\">НАСТРОИТЬ ВО ВХОДАХ</em>':''}</button>`}
function focusSystemTrigger(type){const node=brainTriggerNodes().find(n=>n.type===type);if(!node)return;hideOverlay();brainTriggerHubOpen=true;activeBrainTriggerId=node.id;brainConnectFromId=null;activeBrainNodeId=null;renderBrain();requestAnimationFrame(()=>document.querySelector('[data-trigger-hub]')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function showNodeLibrary(){if(replayMode)return;const families=BRAIN_FAMILY_ORDER.map(f=>({family:f,nodes:familyNodes(f).filter(n=>n.availableInSlice!==false)})).filter(group=>group.nodes.length);overlay.innerHTML=`<div class=\"overlay-card brain-library\"><p class=\"kicker\">БИБЛИОТЕКА</p><h3>ДОБАВИТЬ УЗЕЛ</h3><div class=\"brain-library-accordion\">${families.map((group,i)=>`<section class=\"brain-library-section ${i===0?'open':''}\" data-library-family=\"${group.family}\"><button type=\"button\" class=\"brain-library-section__head\" data-library-toggle=\"${group.family}\" aria-expanded=\"${i===0}\"><strong>${group.family}</strong><b>${group.nodes.length}</b><i>${i===0?'−':'+'}</i></button><div class=\"brain-library-section__body\">${group.nodes.map(spec=>libraryNodeHtml(spec,group.family)).join('')}</div></section>`).join('')}</div><button class=\"secondary-reset\" id=\"close-overlay\">ЗАКРЫТЬ</button></div>`;overlay.hidden=false;overlay.querySelectorAll('[data-library-toggle]').forEach(button=>button.addEventListener('click',()=>{const family=button.dataset.libraryToggle;overlay.querySelectorAll('.brain-library-section').forEach(section=>{const open=section.dataset.libraryFamily===family;section.classList.toggle('open',open);section.querySelector('[data-library-toggle]')?.setAttribute('aria-expanded',String(open));const icon=section.querySelector('.brain-library-section__head i');if(icon)icon.textContent=open?'−':'+'})}));overlay.querySelectorAll('[data-open-trigger-type]').forEach(button=>button.addEventListener('click',()=>focusSystemTrigger(button.dataset.openTriggerType)));overlay.querySelectorAll('[data-add-brain-node]').forEach(b=>b.addEventListener('click',()=>{const node=addBrainNode(currentBrainGraph,b.dataset.addBrainNode);activeBrainNodeId=node.id;activeBrainPresetId='custom';brainConnectFromId=null;rebuildBrainSequence();hideOverlay();renderBrain();requestAnimationFrame(()=>document.querySelector(`[data-brain-node-wrap=\"${CSS.escape(node.id)}\"]`)?.scrollIntoView({behavior:'smooth',block:'center'}))}));$('#close-overlay').onclick=hideOverlay}
"""
text=replace_between(text,'function showNodeLibrary()','function renderBrain()',library_block)

app.write_text(text,encoding='utf-8')

# Library accordion / gameplay-card styling.
css=ROOT/'add-node-picker.css'
css.write_text(r'''.overlay-card.brain-library{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(620px,calc(100vw - 40px));max-height:min(760px,88dvh);overflow:auto;margin:0;padding:0;background:var(--paper);color:var(--ink);border:3px solid var(--ink);z-index:130;overscroll-behavior:contain}.overlay-card.brain-library>.kicker{margin:0;padding:18px 76px 4px 16px;font:900 11px/1 monospace}.overlay-card.brain-library>h3{margin:0;padding:0 76px 17px 16px;border-bottom:3px solid var(--ink);font-size:22px;line-height:1}.brain-library-accordion{margin:0}.brain-library-section{margin:0;border-bottom:2px solid var(--ink)}.brain-library-section__head{width:100%;min-height:54px;margin:0;border:0;background:var(--paper);display:grid;grid-template-columns:1fr 36px 28px;align-items:center;gap:8px;padding:0 14px;text-align:left}.brain-library-section__head:active{transform:none;background:var(--acid)}.brain-library-section__head strong{font:900 13px/1 monospace}.brain-library-section__head b{display:grid;place-items:center;width:30px;height:30px;border:2px solid var(--ink);font:900 12px/1 monospace}.brain-library-section__head i{font:900 23px/1 monospace;font-style:normal;text-align:center}.brain-library-section__body{display:none;padding:10px 14px 14px;gap:8px;background:#ead2a8}.brain-library-section.open .brain-library-section__body{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.brain-library-node{position:relative;display:block;width:100%;min-height:84px;margin:0;padding:10px 58px 10px 12px;border:2px solid var(--ink);background:var(--paper);color:var(--ink);text-align:left}.brain-library-node:active{transform:none;background:var(--acid)}.brain-library-node__family{display:block;font-size:11px;line-height:1;text-transform:lowercase}.brain-library-node__title{display:block;font-size:18px;line-height:1.02;margin-top:3px}.brain-library-node__description{display:block;font-size:11px;line-height:1.15;margin-top:4px}.brain-library-node__value{position:absolute;right:12px;top:50%;transform:translateY(-50%);font:900 16px/1 monospace}.brain-library-node__system{display:block;margin-top:7px;font:900 9px/1 monospace;font-style:normal;color:#5f5748}.overlay-card.brain-library>#close-overlay{position:absolute;right:14px;top:12px;width:48px;height:48px;min-height:48px;margin:0;padding:0;border:2px solid var(--ink);background:var(--paper);color:var(--ink);font-size:0;z-index:2}.overlay-card.brain-library>#close-overlay::before{content:'×';font-size:28px;font-weight:900;line-height:1}.overlay-card.brain-library>#close-overlay:active{background:var(--acid)}@media(hover:hover){.brain-library-node:hover{background:var(--acid)}}@media(max-width:700px){.overlay-card.brain-library{left:0;top:0;transform:none;width:100vw;height:100dvh;max-height:none;border:0;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);background:var(--paper)}.overlay-card.brain-library>.kicker{padding-top:20px}.overlay-card.brain-library>h3{font-size:23px;padding-bottom:19px}.brain-library-section.open .brain-library-section__body{grid-template-columns:1fr}.brain-library-node{min-height:82px}.overlay-card.brain-library>#close-overlay{top:calc(12px + env(safe-area-inset-top,0px));right:14px}}
''',encoding='utf-8')

stack=ROOT/'brain-stack.css'
stack_text=stack.read_text(encoding='utf-8')
append=r'''
/* Unified CONNECT MODE: same source/target language for stack nodes and Trigger Hub. */
.brain-connect-source-button img{width:30px;height:28px;display:block}.brain-connect-source-button.active,.brain-trigger-row.connection-source .brain-connect-source-button{background:var(--acid)!important;color:var(--ink)!important}.brain-trigger-row.connection-source{outline:4px solid var(--acid);outline-offset:-4px}.brain-trigger-row__actions .brain-connect-source-button{min-width:84px;padding:5px 7px;display:grid;grid-template-columns:28px 1fr;gap:4px;align-items:center;border:0;border-left:1px solid var(--ink);background:transparent;color:inherit;font-size:9px;font-weight:900}.brain-trigger-row__actions .brain-connect-source-button span{display:block}.brain-trigger-disconnect{min-width:76px!important;font-size:9px!important}.brain-trigger-disconnect:disabled{opacity:.28}.brain-trigger-row__actions button:last-child{font-size:9px;min-width:76px}.brain-stack-node.connection-target .brain-stack-connect-target,.brain-trigger-row.connection-target .brain-stack-connect-target{background:var(--acid);color:var(--ink)}
'''
if '/* Unified CONNECT MODE:' not in stack_text:
    stack.write_text(stack_text+'\n'+append,encoding='utf-8')

# Browser contract: fixed trigger alphabet, one-open accordion, unified connect mode, no trigger delete.
test=ROOT/'tests/browser-smoke.mjs'
t=test.read_text(encoding='utf-8')
start=t.index("await page.locator('[data-brain-preset=\"custom\"]')")
end=t.index("await page.locator('[data-brain-preset=\"always-right\"]')",start)
replacement="""await page.locator('[data-brain-preset=\"custom\"]').click();assert.equal(await page.locator('#to-setup').isDisabled(),true,'custom brain with fixed inputs is not runnable before a reaction route exists');assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),6,'custom BRAIN starts with the fixed six-input alphabet');assert.equal(await page.locator('[data-trigger-hub-toggle]').getAttribute('aria-expanded'),'true','custom BRAIN keeps Trigger Hub open for authoring');await page.locator('#brain-add-node').click();assert.equal(await page.locator('.brain-library-section.open').count(),1,'node library opens exactly one accordion section');assert.equal(await page.locator('[data-library-family=\"TRIGGER\"] [data-open-trigger-type]').count(),6,'Trigger library exposes the fixed system alphabet without duplicate add semantics');assert.equal(await page.locator('[data-library-family=\"TRIGGER\"] [data-add-brain-node]').count(),0,'system Trigger types cannot be added as disposable nodes');await page.locator('[data-library-toggle=\"STATE\"]').click();assert.equal(await page.locator('.brain-library-section.open').count(),1,'opening a library family closes the previous family');assert.equal(await page.locator('[data-library-family=\"STATE\"]').getAttribute('class').then(x=>x.includes('open')),true,'requested library family is expanded');assert.equal(await page.locator('[data-add-brain-node=\"interrupt\"]').count(),0,'unsupported ability is not offered');await page.locator('#close-overlay').click();
async function addNode(type){await page.locator('#brain-add-node').click();const card=page.locator(`[data-add-brain-node=\"${type}\"]`);const family=await card.getAttribute('data-node-family');await page.locator(`[data-library-toggle=\"${family}\"]`).click();await card.click();await page.waitForTimeout(30)}
await addNode('beright');await addNode('explain');assert.equal(await page.locator('#brain-graph [data-trigger-hub]').count(),1,'BRAIN projects trigger infrastructure into one hub');assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),6,'fixed trigger alphabet remains visible as chips');assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),2,'main stack shows behavioral body without duplicating trigger infrastructure');assert.equal(await page.locator('#brain-graph .brain-stack-edge').count(),1,'body stack renders its behavioral edge before an entry route is authored');assert.equal(await page.locator('#to-setup').isDisabled(),true,'graph remains blocked until the opening trigger is connected');const impulseWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'БЫТЬ ПРАВЫМ'}).first(),reactionWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'ОБЪЯСНИТЬ'}).first();const impulseId=await impulseWrap.getAttribute('data-brain-node-wrap'),reactionId=await reactionWrap.getAttribute('data-brain-node-wrap');const criticismRow=page.locator('[data-trigger-row]').filter({hasText:'КРИТИКА'}).first(),triggerId=await criticismRow.getAttribute('data-trigger-row');assert.equal(await criticismRow.locator('[data-trigger-disconnect]').isDisabled(),true,'unwired system trigger can be connected but not deleted');await criticismRow.locator('[data-trigger-connect]').click();assert.equal(await page.locator('#brain-graph').getAttribute('data-connect-from'),triggerId,'Trigger Hub enters the same global CONNECT MODE');assert.ok(await page.locator('#brain-graph .connection-target').count()>=1,'same compatible target treatment is used for Trigger and ordinary sources');await page.locator(`[data-brain-target=\"${impulseId}\"]`).click();assert.equal(await page.locator('#to-setup').isDisabled(),false,'opening trigger route makes the graph runnable');assert.match(await criticismRow.textContent(),/БЫТЬ ПРАВЫМ/,'Trigger Hub shows the authored destination');assert.equal(await criticismRow.locator('[data-trigger-delete]').count(),0,'fixed system Trigger is never exposed as a delete action');assert.equal(await criticismRow.locator('[data-trigger-disconnect]').isDisabled(),false,'wired Trigger can disconnect its routes without deleting the Trigger');await page.locator(`[data-brain-node=\"${impulseId}\"]`).click();assert.equal(await impulseWrap.getAttribute('class').then(x=>x.includes('open')),true,'tap opens local node controls');await page.locator(`[data-brain-param=\"${impulseId}\"]`).click();assert.equal(await page.locator('.brain-control-backdrop').count(),1,'numeric parameter opens the mobile bottom sheet');const slider=page.locator('.brain-control-range__inner');await slider.focus();await page.keyboard.press('ArrowRight');assert.equal(await page.locator('.brain-control-range__thumb').textContent(),'4','large custom thumb mutates the real impulse value');await page.locator('.brain-control-backdrop').click({position:{x:4,y:4}});await page.waitForTimeout(20);await page.locator(`[data-brain-node=\"${impulseId}\"]`).click();await page.locator(`[data-brain-connect=\"${impulseId}\"]`).click();assert.equal(await page.locator('#brain-graph').getAttribute('data-connect-from'),impulseId,'ordinary node enters the same global CONNECT MODE');assert.ok(await page.locator('#brain-graph .connection-target').count()>=1,'ordinary node uses the same compatible target state');await page.locator(`[data-brain-target=\"${reactionId}\"]`).click();await page.waitForTimeout(20);const reactionHandle=page.locator(`[data-brain-drag=\"${reactionId}\"]`),reactionHandleBox=await reactionHandle.boundingBox(),impulseBox=await impulseWrap.boundingBox();assert.ok(reactionHandleBox&&impulseBox,'drag geometry exists');await page.mouse.move(reactionHandleBox.x+reactionHandleBox.width/2,reactionHandleBox.y+reactionHandleBox.height/2);await page.mouse.down();await page.mouse.move(reactionHandleBox.x+reactionHandleBox.width/2,impulseBox.y+impulseBox.height/2,{steps:4});await page.mouse.up();await page.waitForTimeout(40);assert.equal(await page.locator(`[data-trigger-row=\"${triggerId}\"]`).count(),1,'Trigger Hub survives body reorder');

"""
t=t[:start]+replacement+t[end:]
test.write_text(t,encoding='utf-8')

print('BRAIN connect interaction contract applied')
